submit = async () => {
    const trimmedName = name.trim()
    if (!trimmedName) {
      setError('Enter a profile name before creating it.')
      return
    }
    setSaving(true)
    setError(null)
    try {
      await context.call('quirky.browser/profileCreate', { name: trimmedName })
      await onCreated(trimmedName)
      onCancel()
    } catch (cause) {
      const message = errorMessage(cause)
      setError(message)
      onError(message)
    } finally {
      setSaving(false)
    }
  }

